import{_ as t,o as e,c as o,a0 as r}from"./chunks/framework.Caz7a20Z.js";const u=JSON.parse('{"title":"改论文改到怀疑人生","description":"修改论文很痛苦，发现自己越来越依赖 AI、越来越懒，心里没底；事太多，不知道该把什么放进主线。","frontmatter":{"title":"改论文改到怀疑人生","date":"2026-08-20T00:00:00.000Z","tags":["日记"],"description":"修改论文很痛苦，发现自己越来越依赖 AI、越来越懒，心里没底；事太多，不知道该把什么放进主线。"},"headers":[],"relativePath":"posts/diary-20260820.md","filePath":"posts/diary-20260820.md","lastUpdated":1787215089000}'),s={name:"posts/diary-20260820.md"};function i(n,a,p,l,d,c){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="改论文改到怀疑人生" tabindex="-1">改论文改到怀疑人生 <a class="header-anchor" href="#改论文改到怀疑人生" aria-label="Permalink to &quot;改论文改到怀疑人生&quot;">​</a></h1><p>今天一整天基本都耗在改论文上了，改得我有点怀疑人生。</p><h2 id="越用-ai-越懒" tabindex="-1">越用 AI 越懒 <a class="header-anchor" href="#越用-ai-越懒" aria-label="Permalink to &quot;越用 AI 越懒&quot;">​</a></h2><p>说实话，我现在干什么都想先问一句 AI：这句话怎么改、这段逻辑怎么顺、这个图怎么画、这个数据怎么解释……它确实快，快到我几乎不用动脑子。</p><p>但问题也来了——<strong>我发现自己变懒了</strong>。以前遇到问题会自己先琢磨半天，现在第一反应是&quot;丢给 AI 算了&quot;。省下来的时间并没有用来想更深的问题，反而让我对&quot;自己能不能独立搞定&quot;越来越没底。</p><p>最纠结的是：完全让它做，我心里不踏实，总觉得哪里没把握、不知道它给的答案靠不靠谱；可要是自己从头来，又慢得让人烦躁。</p><h2 id="事太多-不知道主线在哪" tabindex="-1">事太多，不知道主线在哪 <a class="header-anchor" href="#事太多-不知道主线在哪" aria-label="Permalink to &quot;事太多，不知道主线在哪&quot;">​</a></h2><p>除了论文，手头还堆着一堆事：博客要维护、技术要学、实验要做、各种零碎的想法要记录。每次想理一理，都发现<strong>做的内容太多了，整理起来太难</strong>。</p><p>哪些该放进主线认真做、哪些只是顺手玩玩的副线，我纠结了很久。这个想留，那个舍不得丢，最后什么都没真正推进。</p><h2 id="今天的一点想法" tabindex="-1">今天的一点想法 <a class="header-anchor" href="#今天的一点想法" aria-label="Permalink to &quot;今天的一点想法&quot;">​</a></h2><p>写着写着，倒想明白了一点：</p><ul><li><strong>AI 是加速器，不是代驾</strong>。可以借它提速，但方向盘得在自己手里——至少得能看懂它给的答案、能判断对不对。</li><li><strong>主线不是选出来的，是做出来的</strong>。与其纠结哪些事&quot;配&quot;进主线，不如先把眼前最重要的一件做完，主线自然就清晰了。</li></ul><p>明天先把论文里最卡的一节啃下来，全程自己写一遍，再让 AI 帮我挑毛病。试试这种感觉。</p><p>晚安。</p>',14)])])}const _=t(s,[["render",i]]);export{u as __pageData,_ as default};
